import request from '@/utils/request'
const base = '/commercialization'
const call = (url, method = 'get', data, params) => request({ url: base + url, method, data, params })
export const getCreditTypes = () => call('/credit-types')
export const getContentScopes = () => call('/content-scopes')
export const createContentScope = config => call('/content-scopes','post',config)
export const saveContentScope = (config,revision) => call('/content-scopes','put',{config,revision})
export const assignScopeContents = data => call('/content-scope-contents', 'post', data)
export const listConfigs = (entity, params) => call(`/${entity}`, 'get', undefined, params)
export const getConfig = (entity, id) => call(`/${entity}/${id}`)
export const createConfig = (entity, data) => call(`/${entity}`, 'post', data)
export const saveConfig = (entity, id, config, revision) => call(`/${entity}/${id}`, 'put', { config, revision })
export const publishConfig = (entity, id, revision) => call(`/${entity}/${id}/publish`, 'post', { revision })
export const discardConfig = (entity, id, revision) => call(`/${entity}/${id}/discard`, 'post', { revision })
export const deleteConfig = (entity, id, revision) => call(`/${entity}/${id}`, 'delete', { revision })
export const previewConfig = (entity, id, config) => call(`/${entity}/${id}/preview`, 'post', { config })
export const configHistory = (entity, id) => call(`/${entity}/${id}/history`)
export const bulkContent = data => call('/content-bulk', 'post', data)
export const overview = () => call('/overview')
export const listUsers = params => call('/users', 'get', undefined, params)
export const getUser = id => call(`/users/${id}`)
export const listLedger = params => call('/ledger', 'get', undefined, params)
export const listOrders = params => call('/orders', 'get', undefined, params)
export const getOrder = id => call(`/orders/${id}`)
export const listSubscriptions = params => call('/subscriptions', 'get', undefined, params)
export const listRedemptions = params => call('/redemptions', 'get', undefined, params)
export const listUsage = params => call('/usage', 'get', undefined, params)
export const listCampaignRuns = params => call('/campaign-runs', 'get', undefined, params)
export const listAudit = params => call('/audit', 'get', undefined, params)
export const access = data => call('/access', 'post', data)
export const quotePurchase = data => call('/purchase-quote', 'post', data)
export const purchase = data => call('/purchase', 'post', data)
export const retryFulfillment = id => call(`/orders/${id}/retry`, 'post')
export const setRenewal = (id, enabled, reason) => call(`/subscriptions/${id}/renewal`, 'post', { enabled, reason })
export const restorePurchases = userId => call('/restore-purchases', 'post', { userId })
export const renewDemo = (id, data) => call(`/subscriptions/${id}/demo-renew`, 'post', data)
export const quoteService = data => call('/service-quote', 'post', data)
export const startService = data => call('/service-start', 'post', data)
export const finishService = (id, outcome) => call(`/usage/${id}/finish`, 'post', { outcome })
export const quoteRedemption = data => call('/redemption-quote', 'post', data)
export const redeem = data => call('/redeem', 'post', data)
export const compensate = data => call('/compensate', 'post', data)
export const runCampaign = data => call('/campaign-run', 'post', data)
export const demoExpire = data => call('/demo-expire', 'post', data)
export const getStorefront = id => call(`/storefront/${id}`)
export const getWeeklyReport = userId => call(`/weekly-report/${userId}`)
export const readWeeklyReport = (userId,reportId) => call('/weekly-report/read','post',{userId,reportId})
export const joinChallenge = data => call('/challenge-join','post',data)
export const getAsset = (userId, id) => call(`/users/${userId}/assets/${id}`)
export const requestKey = () => window.crypto.randomUUID()
export const money = (cents, currency = 'USD') => new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(cents / 100)
